  [1213754] = { "Il tuo Doppio Attacco ora colpisce $N1 bersaglio vicino aggiuntivo e fa sì che anche il tuo ⟦Sinister Strike=Assalto Funesto⟧ colpisca $N2 bersaglio vicino aggiuntivo per $D1. Questi colpi aggiuntivi non vengono duplicati da ⟦Blade Flurry=Vortice di Lame⟧.", nil, 0x6dc4ac14, nil, "um" },
  [1213759] = { "Mentre è attivo, il tuo Doppio Attacco ti cura anche del $N1% di tutti i danni inflitti da ⟦Sinister Strike=Assalto Funesto⟧. Le cure in eccesso diventano una Barriera di Sangue che assorbe danni fino al $N2% della tua salute massima.", nil, 0x514d70a2, nil, "um" },
  [1213761] = { nil, "Assorbe $N1 danni.", nil, 0xbd35a1c1, "mu" },
  [1213763] = { "Le tue mosse risolutive costano il $N1% di energia in meno.", nil, 0xd1489c05, nil, "um" },
  [1213810] = { "La tua Marea Gelida aumenta di un ulteriore $N1% le cure di ⟦Chain Heal=Catena di Guarigione⟧.", nil, 0xc798e64f, nil, "um" },
  [1213813] = { "Quando subisci un attacco, infligge $N1 danni da natura all'attaccante. Genera una minaccia pari al doppio dei danni inflitti.", nil, 0xfb929eda, nil, "um" },
  [1213816] = { "Quando subisci un attacco, infligge $N1 danni da natura all'attaccante. Genera una minaccia pari al doppio dei danni inflitti.", nil, 0xfb929eda, nil, "um" },
  [1213829] = { "Aumenta in modo permanente fino a $N1 i danni e le cure degli incantesimi di un oggetto indossato su torso, gambe, mani o piedi. Utilizzabile solo su oggetti di livello $N2 o superiore.", nil, 0xc1799147, nil, "um" },
  [1213830] = { "Aumenta i danni e le cure di incantesimi ed effetti magici fino a un massimo di $N1.", nil, 0x76cbff0e, nil, "um" },
  [1213833] = { "Fa sì in modo permanente che un oggetto indossato su torso, gambe, mani o piedi infligga $N1 danni da natura all'attaccante quando subisci un attacco. Utilizzabile solo su oggetti di livello $N2 o superiore.", nil, 0xf6962af8, nil, "um" },
  [1213834] = { "Quando subisci un attacco, infligge $N1 danni da natura all'attaccante. Genera una minaccia pari al doppio dei danni inflitti.", nil, 0xfb929eda, nil, "um" },
  [1213862] = { "Quando subisci un attacco, hai una probabilità del $N1% di sottrarre $N2 salute al nemico bersaglio.", nil, 0x6c4c1fa1, nil, "um" },
  [1213864] = { "Sottrae $N1 salute al bersaglio nemico.", nil, 0x8e44b266, nil, "um" },
  [1213873] = { "Sottrae $N1 salute al bersaglio nemico.", nil, 0x8e44b266, nil, "um" },
  [1213874] = { "Quando subisci un attacco, hai una probabilità del $N1% di sottrarre $N2 salute al nemico bersaglio.", nil, 0x65081da9, nil, "um" },
  [1213886] = { "Aumenta fino a $N1 le cure di incantesimi ed effetti magici, fino a $N2 i danni di incantesimi ed effetti magici e di $N3 mana ogni $N4 s la rigenerazione del mana per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Cure aumentate di $N1.\nDanni degli incantesimi aumentati di $N2.\nRigenera $N3 mana ogni $D1.", 0xc56ee57b, 0x325db2fe, "uu" },
  [1213892] = { "Aumenta fino a un massimo di $N1 i danni inflitti da incantesimi ed effetti magici per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Danni magici aumentati di $N1.", 0x866d214b, 0x62db0716, "uu" },
  [1213894] = { "Riduce di $D1 il tempo di lancio di ⟦Chain Heal=Catena di Guarigione⟧.", nil, 0x7b104225, nil, "um" },
  [1213897] = { "Aumenta la potenza d'attacco di $N1 per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Potenza d'attacco aumentata di $N1.", 0xe7205ee1, 0x564bbf31, "uu" },
  [1213900] = { "Hai una probabilità del $N1% di evitare l'interruzione causata dai danni durante il lancio di ⟦Lightning Bolt=Dardo Fulminante⟧, ⟦Chain Lightning=Catena di Fulmini⟧ o ⟦Lava Burst=Getto di Lava⟧, e una probabilità superiore del $N2% di attivare il talento Focus Elementale.", nil, 0xcfd99980, nil, "um" },
  [1213901] = { "Aumenta la Tempra di $N1 e il valore di difesa di $N2 per $D1. Puoi beneficiare dell'effetto di un solo tonico alla volta. L'effetto persiste dopo la morte.", "Tempra aumentata di $N1.\nDifesa aumentata di $N2.", 0x678ed333, 0xa407e17a, "uu" },
  [1213902] = { "Aumenta del $N1% il bonus ai danni dei colpi critici dei tuoi incantesimi di fuoco, di gelo e di natura.", nil, 0x21a58392, nil, "um" },
  [1213904] = { "Aumenta l'Agilità di $N1, la probabilità di critico del $N2% e la ⟦Nature Resistance=Resistenza alla Natura⟧ di $N3 per $D1.", "Agilità aumentata di $N1.\nProbabilità di critico aumentata del $N2%.\n⟦Nature Resistance=Resistenza alla Natura⟧ aumentata di $N3.", 0x71e89706, 0x94c24bd2, "uu" },
  [1213910] = { "Aumenta del $N1% i danni di Assalto della Tempesta e Sferzata Lavica. L'effetto sale al $N2% se usi un'arma a due mani.", nil, 0x42150fd2, nil, "um" },
  [1213914] = { "Aumenta fino a $N1 i danni degli incantesimi e la ⟦Nature Resistance=Resistenza alla Natura⟧ di $N2 per $D1.", "Danni magici inflitti da incantesimi e abilità aumentati fino a $N1.\n⟦Nature Resistance=Resistenza alla Natura⟧ aumentata di $N2.", 0x8c990f8f, 0xf137f8dd, "uu" },
  [1213915] = { nil, "In fiamme.", nil, 0xfaec4c73, "mu" },
  [1213917] = { "Aumenta l'Armatura di $N1, il valore di difesa di $N2 e la ⟦Nature Resistance=Resistenza alla Natura⟧ di $N3 per $D1.", "Armatura aumentata di $N1.\nDifesa aumentata di $N2.\n⟦Nature Resistance=Resistenza alla Natura⟧ aumentata di $N3.", 0x43ce1fc4, 0xe49ec3b5, "uu" },
  [1213918] = { "I colpi critici di Assalto della Tempesta, Sferzata Lavica e ⟦Lava Burst=Getto di Lava⟧ fanno bruciare il bersaglio, infliggendogli il $N1% dei danni inflitti in $D1.", nil, 0x74c2f166, nil, "um" },
  [1213922] = { "Aumenta la velocità di movimento del personaggio del $N1% per $D1.", "Velocità di movimento aumentata di $N1.", 0xbd3f1cfa, 0xc6b86931, "uu" },
  [1213924] = { "Prosciuga $N1 mana a chi si trova nel raggio dell'esplosione e infligge al bersaglio danni pari al $N2% del mana prosciugato. Inoltre silenzia per $D1 i bersagli colpiti dall'esplosione.", "Silenziato.", 0xecefecaa, 0x20816e34, "uu" },
  [1213930] = { "Infliggere danni a un bersaglio con Assalto della Tempesta, ⟦Lava Burst=Getto di Lava⟧ o ⟦Molten Blast=Detonazione Fusa⟧ riduce anche del $N1% tutti i danni che subisci per $D1.", nil, 0x9cff1b8a, nil, "um" },
  [1213934] = { nil, "Riduce del $N1% tutti i danni subiti.", nil, 0x11733ab1, "mu" },
  [1213935] = { "Esplode quando viene attivato, infliggendo $N1 danni da fuoco a tutti i nemici vicini e $N2 danni a te. Infligge danni extra ai Silitidi di ⟦Silithus=Silitus⟧.", nil, 0xe80282d5, nil, "um" },
  [1213937] = { "Quando lanci Spirit of the Alpha su te stesso, aumenta anche la tua salute del $N1%, la minaccia che generi del $N2% e tutti i danni che infliggi del $N3%.", nil, 0x8352253e, nil, "um" },
  [1213939] = { nil, "Aumenta la salute massima del $N1%, la minaccia generata del $N2% e tutti i danni inflitti del $N3%.", nil, 0x34fcec9c, "mu" },
  [1213946] = { "Infligge $N1 danni da fuoco in un raggio di $N2 m.", nil, 0xd71f6a9c, nil, "um" },
  [1213955] = { "Si apre in un G00 DV-1B3 Generator che può riparare gli oggetti danneggiati e acquistare la merce indesiderata. Dopo $D1 il suo motore interno si guasta e deve riprendersi.", nil, 0x617b4c94, nil, "um" },
  [1213957] = { "I danni del tuo ⟦Lava Burst=Getto di Lava⟧ aumentano di una percentuale pari alla tua probabilità di critico con gli incantesimi.", nil, 0x93981b1d, nil, "um" },
  [1213963] = { "Quando lo scudo blocca un colpo, rilascia una scarica elettrica che danneggia tutti i nemici vicini.", nil, 0xb05d31e0, nil, "um" },
  [1213967] = { "Carica l'energia dello scudo per $D1 per infliggere $N2 danni da natura a tutti i nemici vicini. Dopo l'uso, lo scudo impiega $D2 per ricaricarsi.", "In fase di carica.", 0xf9469222, 0x77eb19c0, "uu" },
  [1213971] = { "Aumenta la tua velocità d'attacco del $N1%.", nil, 0xdd436c29, nil, "um" },
